import{_ as r}from"./chunks/platform-page-layout.J_XGDqLD.js";import{_ as o,c as a,o as d,a7 as s}from"./chunks/framework.DLVsJyUe.js";const n="/ruidu-docs/images/orbitcontrol/user-guide/platform-menu-notification.png",e="/ruidu-docs/images/orbitcontrol/user-guide/platform-menu-user.png",b=JSON.parse('{"title":"平台总览","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/platform.md","filePath":"orbitcontrol/user-guide/platform.md"}'),i={name:"orbitcontrol/user-guide/platform.md"};function l(g,t,h,p,c,u){return d(),a("div",null,t[0]||(t[0]=[s('<h1 id="平台总览" tabindex="-1">平台总览 <a class="header-anchor" href="#平台总览" aria-label="Permalink to &quot;平台总览&quot;">​</a></h1><p>登录并进入企业后，平台整体布局分为三部分：<strong>顶部栏</strong>、<strong>左侧导航栏</strong>和<strong>主内容区</strong>（大部分页面以地图为底）。</p><p><img src="'+r+'" alt=""></p><h2 id="左侧导航" tabindex="-1">左侧导航 <a class="header-anchor" href="#左侧导航" aria-label="Permalink to &quot;左侧导航&quot;">​</a></h2><p>导航栏按功能域分为五组，与本手册的章节一一对应：</p><table tabindex="0"><thead><tr><th>分组</th><th>页面</th><th>说明</th></tr></thead><tbody><tr><td><strong>实况</strong></td><td>设备控制、视频墙</td><td>实时操控与监控</td></tr><tr><td><strong>任务规划</strong></td><td>任务、计划、自动化流程、标注、路网</td><td>任务的编排与调度</td></tr><tr><td><strong>数据中心</strong></td><td>语音库、运行日志、画廊、回放</td><td>运行产出与历史数据</td></tr><tr><td><strong>区域</strong></td><td>电子围栏、禁飞区</td><td>区域限制（随无人机支持陆续开放）</td></tr><tr><td><strong>管理</strong></td><td>站点、设备、地图、用户、组织、应用、企业</td><td>平台配置（需管理员权限）</td></tr></tbody></table><p>点击导航栏顶部按钮可折叠/展开导航栏，为主内容区腾出空间。</p><h2 id="顶部栏" tabindex="-1">顶部栏 <a class="header-anchor" href="#顶部栏" aria-label="Permalink to &quot;顶部栏&quot;">​</a></h2><p>从左到右依次为：</p><ul><li><strong>Logo</strong>：点击回到首页（设备控制）</li><li><strong>主题切换</strong>：在亮色/暗色主题间切换</li><li><strong>通知</strong>：查看平台通知，详见下文</li><li><strong>用户菜单</strong>：账户管理、切换企业、退出登录</li></ul><h3 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h3><p><img src="'+n+'" alt="" class="w-1/2"></p><p>通知按时间倒序、以日期分组展示，每条通知包含来源、标题和内容：</p><ul><li>左侧色条表示级别：<strong>绿色</strong>成功、<strong>红色</strong>失败、<strong>蓝色</strong>普通</li><li>顶部可按「所有 / 失败 / 成功」筛选</li><li>未读通知在铃铛图标上显示数量角标；单条通知悬停后可标记已读，也可点击「全部已读」一键清除</li></ul><h3 id="用户菜单" tabindex="-1">用户菜单 <a class="header-anchor" href="#用户菜单" aria-label="Permalink to &quot;用户菜单&quot;">​</a></h3><p>用户菜单展示当前登录用户与所属企业（含你在该企业中的角色），提供以下功能：</p><table tabindex="0"><thead><tr><th>菜单项</th><th>说明</th></tr></thead><tbody><tr><td><strong>账户管理</strong></td><td>修改个人信息与界面语言</td></tr><tr><td><strong>切换企业</strong></td><td>一个账号可加入多个企业，在此切换当前操作的企业</td></tr><tr><td><strong>创建或加入企业</strong></td><td>新建企业或使用邀请码申请加入</td></tr><tr><td><strong>企业管理</strong></td><td>仅所有者/管理员可见，进入企业管理页面</td></tr><tr><td><strong>退出登录</strong></td><td>退出当前账号</td></tr></tbody></table><p><img src="'+e+'" alt="" class="w-1/3"></p>',18)]))}const f=o(i,[["render",l]]);export{b as __pageData,f as default};
